+
 void reshape_and_cache(
     torch::stable::Tensor& key,    // [num_tokens, num_heads, head_size]
     torch::stable::Tensor& value,  // [num_tokens, num_heads, head_size]
@@ -797,14 +954,34 @@ void reshape_and_cache(
